document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.id==='city-filter'){S.city=el.value;S.station='';S.agent='';if(S.screen==='records')await loadRecords();await refresh(true);}else if(el.id==='station-filter'){S.station=el.value;S.agent='';if(S.screen==='records')await loadRecords();await refresh(true);}else if(el.id==='agent-filter'){S.agent=el.value;await loadRecords();render();}else if(el.id==='catalog-city'){S.catalogCity=el.value;S.draft=null;render();}}catch(e){fail(e);}});
document.addEventListener('input',ev=>{if(ev.target.id==='team-search'){S.search=ev.target.value;clearTimeout(S.searchTimer);S.searchTimer=setTimeout(()=>{const sel=ev.target.selectionStart;render();const input=document.getElementById('team-search');input?.focus();input?.setSelectionRange(sel,sel);},250);}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target;try{switch(form.id){
 case 'capture-form':await capture(form);break;
 case 'login-form':{if(S.busy)return;S.busy=true;const button=form.querySelector('button');button.disabled=true;try{let user=form.elements.user.value.trim();if(!user.includes('@'))user=user.toLowerCase()+'@pulso-encuestadores.invalid';const {error}=await(await client()).auth.signInWithPassword({email:user,password:form.elements.password.value});if(error)throw new Error('Usuario o contraseña no válidos.');await enterCloud();}catch(e){S.mode=null;S.profile=null;throw e;}finally{S.busy=false;button.disabled=false;}break;}
 case 'demo-profile-form':{if(S.mode!=='demo')throw new Error('Solo práctica.');if(S.syncing)throw new Error('Espere la sincronización.');const role=form.elements.role.value;S.profile=role==='interviewer'?S.meta.profiles.find(p=>p.district_id===form.elements.city.value&&p.slot===Number(form.elements.slot.value)):{id:role==='admin'?'demo-admin':'demo-viewer',code:role==='admin'?'ADMIN-DEMO':'VIEW-DEMO',role,active:true,district_id:null};S.city='all';S.station='';S.agent='';S.records=[];S.screen=role==='interviewer'?'capture':'dashboard';S.geo={geo_status:'not_requested'};S.choice=null;S.started=new Date().toISOString();closeModal();await refresh(true);break;}
 case 'connection-form':{const u=new URL(form.elements.url.value.trim());if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.pathname!=='/'||u.search||u.hash)throw new Error('Use la URL HTTPS raíz de su proyecto Supabase.');const key=form.elements.key.value.trim();let valid=key.startsWith('sb_publishable_');if(!valid&&key.split('.').length===3){try{valid=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).role==='anon';}catch{}}if(!valid)throw new Error('Solo clave publicable o anon. Se rechazó una clave no pública.');if(S.mode)await logout();S.config={...S.config,supabaseUrl:u.origin,supabasePublishableKey:key};localStorage.setItem('pulso-v2-config',JSON.stringify({supabaseUrl:u.origin,supabasePublishableKey:key}));S.sb=null;closeModal();render();break;}
 case 'assignment-form':{if(!admin())throw new Error('Solo administración.');const id=form.dataset.id,st=form.elements.station.value;if(S.mode==='demo'){S.meta.profiles.find(p=>p.id===id).station_id=st;await saveMeta();}else await rpc('set_assignment',{p_user_id:id,p_station_id:st});closeModal();await refresh(true);break;}
 case 'operator-form':{if(!admin())throw new Error('Solo administración.');const id=form.dataset.id,name=form.elements.name.value.trim();if(S.mode==='demo'){S.meta.profiles.find(p=>p.id===id).display_name=name;await saveMeta();}else await rpc('set_operator_label',{p_user_id:id,p_name:name});closeModal();await refresh(true);break;}
 case 'settings-form':{if(!admin())throw new Error('Solo administración.');const p={title:form.elements.title.value.trim(),contest:form.elements.contest.value.trim(),fieldwork_date:form.elements.date.value,sample_interval:Number(form.elements.interval.value),goal_per_district:S.meta.settings.goal_per_district,methodology:form.elements.methodology.value.trim(),catalog_confirmed:form.elements.confirmed.checked};if(S.mode==='demo'){Object.assign(S.meta.settings,p);await saveMeta();}else await rpc('save_settings',{p_settings:p});await refresh(true);toast('Jornada guardada.');break;}
 case 'catalog-form':{if(!admin())throw new Error('Solo administración.');readDraft();const d=S.draft;if(d.candidates.some(c=>!c.name)||d.stations.some(s=>!s.name))throw new Error('Complete nombres y listas.');for(const st of d.stations)if((st.latitude==null)!==(st.longitude==null))throw new Error('Ingrese ambas coordenadas o deje ambas vacías.');if(S.mode==='demo'){const ids=d.stations.map(st=>st.id);if(S.meta.profiles.some(p=>p.district_id===S.catalogCity&&!ids.includes(p.station_id)))throw new Error('No puede quitar un local asignado.');S.meta.candidates=[...S.meta.candidates.filter(c=>c.district_id!==S.catalogCity),...d.candidates.map((c,i)=>({...c,id:c.id||uuid(),district_id:S.catalogCity,sort_order:i,active:true,is_template:false}))];S.meta.stations=[...S.meta.stations.filter(st=>st.district_id!==S.catalogCity),...d.stations.map(st=>({...st,id:st.id||uuid(),district_id:S.catalogCity,active:true,is_template:/práctica|ejemplo|NO OFICIAL/i.test(st.name)||st.address.length<5}))];S.meta.settings.catalog_confirmed=false;await saveMeta();}else await rpc('save_catalog',{p_district_id:S.catalogCity,p_candidates:d.candidates,p_stations:d.stations});S.draft=null;await refresh(true);toast('Catálogo guardado. Revise y confirme la jornada.');break;}
 case 'create-account-form':{if(!admin())throw new Error('Solo administración.');const role=form.elements.role.value,code=form.elements.code.value.trim().toUpperCase(),city=form.elements.city.value||null,name=form.elements.name.value.trim();if(role==='admin'&&!confirm('Esta cuenta tendrá acceso completo a administración y registros. ¿Confirmar?'))break;if(S.mode==='demo'){S.meta.profiles.push({id:uuid(),code,role,display_name:name,district_id:role==='admin'?null:city,station_id:null,slot:null,active:true});await saveMeta();closeModal();await loadAccounts();render();toast('Cuenta simulada creada; sin contraseña real.');}else{const submit=form.querySelector('[type=submit]');submit.disabled=true;const r=await edge({action:'create-account',role,code,district_id:city,display_name:name});await loadAccounts();showCredentials([r.credential]);}break;}
 case 'password-form':{if(form.elements.password.value!==form.elements.confirm.value)throw new Error('Las contraseñas no coinciden.');const {error}=await(await client()).auth.updateUser({password:form.elements.password.value});if(error)throw error;closeModal();toast('Contraseña actualizada.');break;}
 }}catch(e){fail(e);form.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false);}});
window.addEventListener('online',()=>{S.lastError='';sync(false);refresh(false);});window.addEventListener('offline',()=>{S.live=false;S.lastError='Sin red. Los pendientes locales todavía no están incluidos en los resultados.';if(S.screen!=='capture'&&!S.modal)render();});document.addEventListener('visibilitychange',()=>{if(!document.hidden){refresh(false);sync(false);}});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&S.modal){const nodes=[...document.querySelectorAll('.modal button:not([disabled]),.modal input:not([disabled]),.modal select:not([disabled]),.modal textarea:not([disabled]),.modal a')];if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
setInterval(()=>{if(S.mode){refresh(false);if(S.mode==='cloud'&&online())rpc('ping').catch(()=>{});if(interviewer())sync(false);}},15000);
async function init(){try{await store.open();}catch{store=new C.VolatileDemoStore();S.volatile=true;}if(CFG.defaultDemo||CFG.standalone){await startDemo();return;}render();if(S.config.supabaseUrl){try{if(navigator.onLine){const sb=await client(),{data}=await sb.auth.getSession();if(data.session)await enterCloud();}else{const uid=localStorage.getItem('pulso-v2-last:'+S.config.supabaseUrl);const cached=uid?await store.get('meta',`session:${S.config.supabaseUrl}:${uid}`):null;if(cached?.value?.profile?.role==='interviewer'){S.mode='cloud';S.meta=cached.value;S.profile=cached.value.profile;S.screen='capture';S.started=new Date().toISOString();S.lastError='Sesión local previa. El servidor validará la cuenta y las capturas al reconectar.';await refreshQueue();render();}}}catch(e){fail(e);S.mode=null;S.profile=null;render();}}if(!CFG.standalone&&'serviceWorker'in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});}
init().catch(fail);
